<?php
declare(strict_types=1);
namespace Plugins\Modules\Phonetics\Http\Controllers;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Http\JsonResponse;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;use Illuminate\View\View;use Plugins\Modules\Phonetics\Models\PhoneticSetting;use Plugins\Modules\Phonetics\Models\PhoneticEntry;use Plugins\Modules\Phonetics\Models\PhoneticAttempt;
final class PhoneticsPracticeController extends Controller{public function index(Request $r,string $courseSlug):View{$s=PhoneticSetting::current();abort_unless($s->enabled,404);abort_if($s->course_scoped_only&&$courseSlug!==$s->course_slug,404);if($s->require_course_enrollment)$this->assertCourseAccess($r,$courseSlug);$e=PhoneticEntry::query()->where('is_active',true)->orderBy('sort_order')->orderBy('word')->get();$q=$r->user()?PhoneticAttempt::query()->where('user_id',$r->user()->id):PhoneticAttempt::query()->whereRaw('1=0');return view('phonetics::practice.index',['setting'=>$s,'entries'=>$e,'stats'=>['attempted'=>(clone $q)->count(),'correct'=>(clone $q)->where('is_correct',true)->count()]]);}public function storeAttempt(Request $r,string $courseSlug):JsonResponse{$s=PhoneticSetting::current();abort_unless($s->enabled,404);abort_if($s->course_scoped_only&&$courseSlug!==$s->course_slug,404);abort_unless($r->user(),401);if($s->require_course_enrollment)$this->assertCourseAccess($r,$courseSlug);$v=$r->validate(['entry_id'=>'required|integer|exists:alom_english_center_phonetic_entries,id','target_accent'=>'required|in:uk,us','quiz_mode'=>'required|in:identify-ipa,identify-accent','selected_answer'=>'required|string|max:120']);$e=PhoneticEntry::query()->whereKey($v['entry_id'])->where('is_active',true)->firstOrFail();$answer=mb_strtolower(trim($v['selected_answer']));$expected=$v['quiz_mode']==='identify-ipa'?mb_strtolower(trim((string)$e->{$v['target_accent'].'_ipa'})):$v['target_accent'];$correct=hash_equals($expected,$answer);$a=PhoneticAttempt::query()->create(['user_id'=>$r->user()->id,'entry_id'=>$e->id,'target_accent'=>$v['target_accent'],'quiz_mode'=>$v['quiz_mode'],'selected_answer'=>trim($v['selected_answer']),'is_correct'=>$correct]);return response()->json(['saved'=>true,'correct'=>$correct,'attempt_id'=>$a->id]);}private function assertCourseAccess(Request $r,string $slug):void{$u=$r->user();abort_unless($u,403,'Sign in and enroll to practice.');if($u->hasRole('admin'))return;abort_unless(Schema::hasTable('enrollments')&&Schema::hasTable('courses'),503,'Course enrollment is unavailable.');$q=DB::table('enrollments')->join('courses','courses.id','=','enrollments.course_id')->where('enrollments.user_id',$u->id)->where('courses.slug',$slug)->whereIn('enrollments.status',['active','completed']);if($u->branch_id!==null)$q->where(fn($b)=>$b->whereNull('enrollments.branch_id')->orWhere('enrollments.branch_id',$u->branch_id))->where(fn($b)=>$b->whereNull('courses.branch_id')->orWhere('courses.branch_id',$u->branch_id));abort_unless($q->exists(),403,'Phonetics practice is restricted to enrolled students.');}}